pair<int, int> twoSum(const vector<int>& nums, int target) {
    unordered_map<int, int> seen;  // value -> index of an earlier element
    for (int i = 0; i < (int)nums.size(); i++) {
        auto it = seen.find(target - nums[i]);  // find() never inserts, unlike []
        if (it != seen.end()) return {it->second, i};
        seen[nums[i]] = i;
    }
    return {-1, -1};
}

