class Solution {
    int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>(); // value -> index of an earlier element
        for (int i = 0; i < nums.length; i++) {
            Integer j = seen.get(target - nums[i]); // look up before inserting: no self-pairing
            if (j != null) return new int[] {j, i};
            seen.put(nums[i], i);
        }
        return new int[] {-1, -1};
    }
}

