// Start index of every occurrence of a non-empty pat in text.
vector<int> findAll(const string& text, const string& pat) {
    int m = pat.size();
    vector<int> pi(m, 0);  // pi[i]: longest proper border of pat[0..i]
    for (int i = 1, j = 0; i < m; i++) {
        while (j && pat[i] != pat[j]) j = pi[j - 1];
        if (pat[i] == pat[j]) j++;
        pi[i] = j;
    }
    vector<int> res;
    for (int i = 0, j = 0; i < (int)text.size(); i++) {
        while (j && text[i] != pat[j]) j = pi[j - 1];
        if (text[i] == pat[j]) j++;
        if (j == m) {
            res.push_back(i - m + 1);
            j = pi[j - 1];  // keep going: matches may overlap
        }
    }
    return res;
}

