// findAll returns the start index of every occurrence of a non-empty pat in text.
func findAll(text, pat string) []int {
	m := len(pat)
	pi := make([]int, m) // pi[i]: longest proper border of pat[:i+1]
	for i, j := 1, 0; i < m; i++ {
		for j > 0 && pat[i] != pat[j] {
			j = pi[j-1]
		}
		if pat[i] == pat[j] {
			j++
		}
		pi[i] = j
	}
	var res []int
	for i, j := 0, 0; i < len(text); i++ {
		for j > 0 && text[i] != pat[j] {
			j = pi[j-1]
		}
		if text[i] == pat[j] {
			j++
		}
		if j == m {
			res = append(res, i-m+1)
			j = pi[j-1] // keep going: matches may overlap
		}
	}
	return res
}

