// Length of the longest substring without repeated characters.
int longestUnique(const string& s) {
    unordered_map<char, int> cnt;  // counts inside the window s[left..right]
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        char c = s[right];
        cnt[c]++;
        while (cnt[c] > 1) cnt[s[left++]]--;  // shrink until the window is valid again
        best = max(best, right - left + 1);
    }
    return best;
}

