// longestUnique returns the length of the longest substring without repeated bytes.
func longestUnique(s string) int {
	cnt := map[byte]int{} // counts inside the window s[left:right+1]
	left, best := 0, 0
	for right := 0; right < len(s); right++ {
		c := s[right]
		cnt[c]++
		for cnt[c] > 1 { // shrink until the window is valid again
			cnt[s[left]]--
			left++
		}
		best = max(best, right-left+1)
	}
	return best
}

