// Number of non-empty subarrays whose sum is k (negatives allowed).
int countSubarrays(const vector<int>& nums, int k) {
    unordered_map<long long, int> seen{{0, 1}};  // prefix sum -> occurrences
    long long pre = 0;
    int ans = 0;
    for (int x : nums) {
        pre += x;
        auto it = seen.find(pre - k);  // sum(j..i) = pre_i - pre_j
        if (it != seen.end()) ans += it->second;
        seen[pre]++;
    }
    return ans;
}

