class Solution {
    // Number of non-empty subarrays whose sum is k (negatives allowed).
    int countSubarrays(int[] nums, int k) {
        Map<Long, Integer> seen = new HashMap<>(); // prefix sum -> occurrences
        seen.put(0L, 1); // the empty prefix
        long pre = 0;
        int ans = 0;
        for (int x : nums) {
            pre += x;
            ans += seen.getOrDefault(pre - k, 0); // sum(j..i) = pre_i - pre_j
            seen.merge(pre, 1, Integer::sum);
        }
        return ans;
    }
}

