// countSubarrays returns how many non-empty subarrays sum to k (negatives allowed).
func countSubarrays(nums []int, k int) int {
	seen := map[int]int{0: 1} // prefix sum -> occurrences; the empty prefix counts once
	pre, ans := 0, 0
	for _, x := range nums {
		pre += x
		ans += seen[pre-k] // sum(j..i) = pre_i - pre_j
		seen[pre]++
	}
	return ans
}

