from typing import Callable


def first_true(lo: int, hi: int, ok: Callable[[int], bool]) -> int:
    """Smallest x in [lo, hi) with ok(x), where ok goes False..False True..True; hi if none."""
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid  # mid may be the answer: keep it in range
        else:
            lo = mid + 1
    return lo


def lower_bound(nums: list[int], target: int) -> int:
    """First index whose value is >= target (len(nums) if none)."""
    return first_true(0, len(nums), lambda i: nums[i] >= target)

