def next_greater(nums: list[int]) -> list[int]:
    """For each i, the first value to the right that is strictly greater, or -1."""
    ans = [-1] * len(nums)
    stack = []  # indexes still waiting; their values decrease from bottom to top
    for i, x in enumerate(nums):
        while stack and nums[stack[-1]] < x:
            ans[stack.pop()] = x
        stack.append(i)
    return ans

