// For each i, the first value to the right that is strictly greater, or -1.
vector<int> nextGreater(const vector<int>& nums) {
    vector<int> ans(nums.size(), -1);
    vector<int> st;  // indexes still waiting; their values decrease from bottom to top
    for (int i = 0; i < (int)nums.size(); i++) {
        while (!st.empty() && nums[st.back()] < nums[i]) {
            ans[st.back()] = nums[i];
            st.pop_back();
        }
        st.push_back(i);
    }
    return ans;
}

