// nextGreater returns, for each i, the first value to the right that is strictly greater, or -1.
func nextGreater(nums []int) []int {
	ans := make([]int, len(nums))
	var st []int // indexes still waiting; their values decrease from bottom to top
	for i, x := range nums {
		ans[i] = -1
		for len(st) > 0 && nums[st[len(st)-1]] < x {
			ans[st[len(st)-1]] = x
			st = st[:len(st)-1]
		}
		st = append(st, i)
	}
	return ans
}

