// Most intervals you can keep with no overlap; [a, b] and [b, c] may touch.
int maxNonOverlapping(vector<vector<int>> intervals) {
    sort(intervals.begin(), intervals.end(),
         [](const vector<int>& a, const vector<int>& b) { return a[1] < b[1]; });
    int count = 0;
    long long end = LLONG_MIN;
    for (auto& iv : intervals)
        if (iv[0] >= end) {  // fits after the last kept interval
            count++;
            end = iv[1];
        }
    return count;
}

