import (
	"math"
	"sort"
)

// maxNonOverlapping returns the most intervals you can keep with no overlap;
// [a, b] and [b, c] may touch.
func maxNonOverlapping(intervals [][]int) int {
	sort.Slice(intervals, func(i, j int) bool { return intervals[i][1] < intervals[j][1] })
	count, end := 0, math.MinInt
	for _, iv := range intervals {
		if iv[0] >= end { // fits after the last kept interval
			count++
			end = iv[1]
		}
	}
	return count
}

