    TreeNode *left, *right;
    TreeNode(int v, TreeNode* l = nullptr, TreeNode* r = nullptr) : val(v), left(l), right(r) {}
};

// Largest sum of any non-empty path between two nodes.
int maxPathSum(TreeNode* root) {
    int best = INT_MIN;
    function<int(TreeNode*)> gain = [&](TreeNode* node) {  // best downward path from node
        if (!node) return 0;
        int left = max(gain(node->left), 0), right = max(gain(node->right), 0);
        best = max(best, node->val + left + right);  // the path that bends at node
        return node->val + max(left, right);         // only one side continues upward
    };
    gain(root);
    return best;
}

