        if (node == null) return 0;
        int left = Math.max(gain(node.left), 0), right = Math.max(gain(node.right), 0);
        best = Math.max(best, node.val + left + right); // the path that bends at node
        return node.val + Math.max(left, right); // only one side continues upward
    }
}

