import "math"

type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

// maxPathSum returns the largest sum of any non-empty path between two nodes.
func maxPathSum(root *TreeNode) int {
	best := math.MinInt
	var gain func(*TreeNode) int // best downward path sum that starts at node
	gain = func(node *TreeNode) int {
		if node == nil {
			return 0
		}
		left, right := max(gain(node.Left), 0), max(gain(node.Right), 0)
		best = max(best, node.Val+left+right) // the path that bends at node
		return node.Val + max(left, right)    // only one side continues upward
	}
	gain(root)
	return best
}

