    TreeNode(int v, TreeNode* l = nullptr, TreeNode* r = nullptr) : val(v), left(l), right(r) {}
};

// Rebuild a tree with distinct values from its preorder and inorder walks.
TreeNode* buildTree(const vector<int>& preorder, const vector<int>& inorder) {
    unordered_map<int, int> pos;  // value -> inorder index: O(1) splits
    for (int i = 0; i < (int)inorder.size(); i++) pos[inorder[i]] = i;
    int next = 0;  // preorder yields roots in exactly the order we build them
    function<TreeNode*(int, int)> build = [&](int lo, int hi) -> TreeNode* {  // inorder [lo, hi)
        if (lo == hi) return nullptr;
        TreeNode* root = new TreeNode(preorder[next++]);
        int mid = pos[root->val];
        root->left = build(lo, mid);  // left before right, matching preorder
        root->right = build(mid + 1, hi);
        return root;
    };
    return build(0, inorder.size());
}

