int kthSmallest(TreeNode* root, int k) {
    stack<TreeNode*> st;
    TreeNode* node = root;
    while (true) {
        for (; node; node = node->left) st.push(node);  // go as far left as possible
        node = st.top();  // the next value in sorted order
        st.pop();
        if (--k == 0) return node->val;
        node = node->right;
    }
}

