// 0 empty, 1 fresh, 2 rotten. Minutes until nothing is fresh, or -1.
int minutesToRot(vector<vector<int>> grid) {
    int rows = grid.size(), cols = grid[0].size(), fresh = 0, minutes = 0;
    queue<pair<int, int>> q;
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == 2) q.push({r, c});
            if (grid[r][c] == 1) fresh++;
        }
    const int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
    while (!q.empty() && fresh) {
        minutes++;
        for (int k = q.size(); k > 0; k--) {  // every rotten cell spreads one step this minute
            auto [r, c] = q.front();
            q.pop();
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] != 1) continue;
                grid[nr][nc] = 2;  // mark when enqueued, not when popped
                fresh--;
                q.push({nr, nc});
            }
        }
    }
    return fresh ? -1 : minutes;
}

