// minutesToRot takes 0 empty, 1 fresh, 2 rotten and returns the minutes until
// nothing is fresh, or -1.
func minutesToRot(grid [][]int) int {
	type cell struct{ r, c int }
	rows, cols := len(grid), len(grid[0])
	var q []cell
	fresh := 0
	for r := range grid {
		for c, v := range grid[r] {
			switch v {
			case 2:
				q = append(q, cell{r, c})
			case 1:
				fresh++
			}
		}
	}
	dirs := []cell{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	minutes := 0
	for len(q) > 0 && fresh > 0 {
		minutes++
		var next []cell // every rotten cell spreads one step this minute
		for _, p := range q {
			for _, d := range dirs {
				nr, nc := p.r+d.r, p.c+d.c
				if nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] != 1 {
					continue
				}
				grid[nr][nc] = 2 // mark when enqueued, not when popped
				fresh--
				next = append(next, cell{nr, nc})
			}
		}
		q = next
	}
	if fresh > 0 {
		return -1
	}
	return minutes
}

