struct DSU {
    vector<int> parent, size;
    int count;  // number of components

    DSU(int n) : parent(n), size(n, 1), count(n) { iota(parent.begin(), parent.end(), 0); }

    int find(int x) {
        while (parent[x] != x) x = parent[x] = parent[parent[x]];  // path halving
        return x;
    }

    bool unite(int a, int b) {
        a = find(a), b = find(b);
        if (a == b) return false;  // already connected: this edge would close a cycle
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;  // hang the smaller tree under the larger
        size[a] += size[b];
        count--;
        return true;
    }
};

