// Edge {u, v} means u comes before v. Returns {} if there is a cycle.
vector<int> topoOrder(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> graph(n);
    vector<int> indeg(n, 0);
    for (auto [u, v] : edges) {
        graph[u].push_back(v);
        indeg[v]++;
    }
    queue<int> q;
    for (int i = 0; i < n; i++)
        if (indeg[i] == 0) q.push(i);
    vector<int> order;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);
        for (int v : graph[u])
            if (--indeg[v] == 0) q.push(v);  // every prerequisite of v is placed
    }
    if ((int)order.size() < n) order.clear();
    return order;
}

