// topoOrder takes edges {u, v} meaning u comes before v; it returns nil if there is a cycle.
func topoOrder(n int, edges [][2]int) []int {
	graph := make([][]int, n)
	indeg := make([]int, n)
	for _, e := range edges {
		graph[e[0]] = append(graph[e[0]], e[1])
		indeg[e[1]]++
	}
	var q []int
	for i, d := range indeg {
		if d == 0 {
			q = append(q, i)
		}
	}
	order := make([]int, 0, n)
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		order = append(order, u)
		for _, v := range graph[u] {
			indeg[v]--
			if indeg[v] == 0 { // every prerequisite of v is placed
				q = append(q, v)
			}
		}
	}
	if len(order) < n {
		return nil
	}
	return order
}

