// Directed edges {u, v, w} with w >= 0. Unreachable nodes get -1.
vector<long long> dijkstra(int n, const vector<array<int, 3>>& edges, int src) {
    vector<vector<pair<int, int>>> graph(n);
    for (auto& [u, v, w] : edges) graph[u].push_back({v, w});
    vector<long long> dist(n, LLONG_MAX);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;  // min-heap
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;  // stale entry: u was settled with a shorter distance
        for (auto [v, w] : graph[u])
            if (d + w < dist[v]) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
    }
    for (auto& d : dist)
        if (d == LLONG_MAX) d = -1;
    return dist;
}

