import "sort"

// mstWeight takes undirected edges {u, v, w} and returns the weight of a minimum
// spanning tree, or -1 if the graph is disconnected.
func mstWeight(n int, edges [][3]int) int {
	sort.Slice(edges, func(i, j int) bool { return edges[i][2] < edges[j][2] })
	parent := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	find := func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	total, used := 0, 0
	for _, e := range edges {
		ru, rv := find(e[0]), find(e[1])
		if ru == rv {
			continue // would close a cycle
		}
		parent[ru] = rv
		total += e[2]
		used++
	}
	if used != n-1 {
		return -1
	}
	return total
}

