    function<void(int)> dfs = [&](int start) {
        res.push_back(path);  // copies path
        for (int i = start; i < (int)nums.size(); i++) {
            if (i > start && nums[i] == nums[i - 1]) continue;  // already tried at this level
            path.push_back(nums[i]);
            dfs(i + 1);
            path.pop_back();  // undo the choice
        }
    };
    dfs(0);
    return res;
}

