// Cheapest path from top-left to bottom-right moving only right or down.
int minPathSum(const vector<vector<int>>& grid) {
    int cols = grid[0].size();
    vector<int> dp(cols, INT_MAX);  // before row r is filled, dp[c] holds row r-1
    dp[0] = 0;
    for (auto& row : grid)
        for (int c = 0; c < cols; c++) {
            int best = c ? min(dp[c], dp[c - 1]) : dp[c];  // from above or from the left
            dp[c] = best + row[c];  // best is always finite here
        }
    return dp[cols - 1];
}

