import "math"

// minPathSum returns the cheapest path from top-left to bottom-right moving only right or down.
func minPathSum(grid [][]int) int {
	cols := len(grid[0])
	dp := make([]int, cols) // before row r is filled, dp[c] holds row r-1
	for c := 1; c < cols; c++ {
		dp[c] = math.MaxInt
	}
	for _, row := range grid {
		for c := range row {
			best := dp[c]
			if c > 0 {
				best = min(best, dp[c-1]) // from above or from the left
			}
			dp[c] = best + row[c] // best is always finite here
		}
	}
	return dp[cols-1]
}

