// Ways to pick a subset (each item at most once) that sums to target.
long long countSubsets(const vector<int>& nums, int target) {
    vector<long long> dp(target + 1, 0);  // dp[s]: ways to reach sum s
    dp[0] = 1;
    for (int x : nums)
        for (int s = target; s >= x; s--) dp[s] += dp[s - x];  // backwards: x used at most once
    return dp[target];
}

// Ways to make amount with unlimited coins, order ignored.
long long countCombinations(const vector<int>& coins, int amount) {
    vector<long long> dp(amount + 1, 0);
    dp[0] = 1;
    for (int coin : coins)  // coins outside: each multiset is counted once
        for (int s = coin; s <= amount; s++) dp[s] += dp[s - coin];  // forwards: reuse allowed
    return dp[amount];
}

