class Solution {
    // Length of the longest strictly increasing subsequence.
    int lisLength(int[] nums) {
        int[] tails = new int[nums.length]; // tails[k]: smallest tail of length k+1
        int len = 0;
        for (int x : nums) {
            int lo = 0, hi = len; // first index with tails[i] >= x (use > for non-decreasing)
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (tails[mid] >= x) hi = mid;
                else lo = mid + 1;
            }
            tails[lo] = x;
            if (lo == len) len++;
        }
        return len;
    }
}

