// Largest product of a non-empty contiguous subarray.
long long maxProduct(const vector<int>& nums) {
    long long hi = nums[0], lo = nums[0], best = nums[0];  // max and min product ending here
    for (size_t i = 1; i < nums.size(); i++) {
        long long x = nums[i];
        long long a = hi * x, b = lo * x;  // a negative x swaps max and min
        hi = max({x, a, b});  // restart, or extend
        lo = min({x, a, b});
        best = max(best, hi);
    }
    return best;
}

