// maxProduct returns the largest product of a non-empty contiguous subarray.
func maxProduct(nums []int) int {
	hi, lo, best := nums[0], nums[0], nums[0] // max and min product ending here
	for _, x := range nums[1:] {
		a, b := hi*x, lo*x                  // a negative x swaps max and min
		hi, lo = max(x, a, b), min(x, a, b) // restart, or extend
		best = max(best, hi)
	}
	return best
}

