// maxProfitCooldown allows unlimited trades, but after selling you must wait
// one day before buying again.
func maxProfitCooldown(prices []int) int {
	hold, cool, free := math.MinInt/2, 0, 0 // profit at the end of a day in each state
	for _, p := range prices {
		// keep holding or buy today (only from free); sell today; rest
		hold, cool, free = max(hold, free-p), hold+p, max(free, cool)
	}
