// Best total profit of non-overlapping jobs; a job may start when another ends.
long long maxProfit(const vector<int>& start, const vector<int>& end, const vector<int>& profit) {
    int n = start.size();
    vector<array<int, 3>> jobs(n);  // {end, start, profit}
    for (int i = 0; i < n; i++) jobs[i] = {end[i], start[i], profit[i]};
    sort(jobs.begin(), jobs.end());
    vector<long long> dp(n + 1, 0);  // dp[i]: best using the first i jobs by end time
    for (int i = 0; i < n; i++) {
        auto [e, s, p] = jobs[i];
        // k = number of earlier jobs that end by time s
        int k = upper_bound(jobs.begin(), jobs.begin() + i, s,
                            [](int t, const array<int, 3>& job) { return t < job[0]; }) - jobs.begin();
        dp[i + 1] = max(dp[i], dp[k] + p);  // skip job i, or take it after the first k jobs
    }
    return dp[n];
}

