class Solution {
    // Best total profit of non-overlapping jobs; a job may start when another ends.
    long maxProfit(int[] start, int[] end, int[] profit) {
        int n = start.length;
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(end[a], end[b]));
        long[] dp = new long[n + 1]; // dp[i]: best using the first i jobs by end time
        for (int i = 0; i < n; i++) {
            int job = order[i];
            int lo = 0, hi = i; // k = number of earlier jobs that end by start[job]
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (end[order[mid]] > start[job]) hi = mid;
                else lo = mid + 1;
            }
            dp[i + 1] = Math.max(dp[i], dp[lo] + profit[job]); // skip it, or take it after them
        }
        return dp[n];
    }
}

