import "sort"

// maxProfit returns the best total profit of non-overlapping jobs; a job may
// start when another ends.
func maxProfit(start, end, profit []int) int {
	n := len(start)
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool { return end[order[a]] < end[order[b]] })
	dp := make([]int, n+1) // dp[i]: best using the first i jobs by end time
	for i, job := range order {
		// k = number of earlier jobs that end by start[job]
		k := sort.Search(i, func(m int) bool { return end[order[m]] > start[job] })
		dp[i+1] = max(dp[i], dp[k]+profit[job]) // skip it, or take it after them
	}
	return dp[n]
}

