// {best if node is taken, best if it is not}
pair<long long, long long> robDfs(TreeNode* node) {
    if (!node) return {0, 0};
    auto [lt, ls] = robDfs(node->left);
    auto [rt, rs] = robDfs(node->right);
    long long take = node->val + ls + rs;          // children must be skipped
    long long skip = max(lt, ls) + max(rt, rs);    // children are free to choose
    return {take, skip};
}

