class Solution {
    // Largest sum of node values with no parent-child pair both taken.
    long robTree(TreeNode root) {
        long[] r = dfs(root);
        return Math.max(r[0], r[1]);
    }

    private long[] dfs(TreeNode node) { // {best if node is taken, best if it is not}
        if (node == null) return new long[] {0, 0};
        long[] l = dfs(node.left), r = dfs(node.right);
        long take = node.val + l[1] + r[1]; // children must be skipped
        long skip = Math.max(l[0], l[1]) + Math.max(r[0], r[1]); // children are free to choose
        return new long[] {take, skip};
    }
}

