type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}

// robTree returns the largest sum of node values with no parent-child pair both taken.
func robTree(root *TreeNode) int {
	var dfs func(*TreeNode) (take, skip int)
	dfs = func(node *TreeNode) (int, int) {
		if node == nil {
			return 0, 0
		}
		lt, ls := dfs(node.Left)
		rt, rs := dfs(node.Right)
		take := node.Val + ls + rs        // children must be skipped
		skip := max(lt, ls) + max(rt, rs) // children are free to choose
		return take, skip
	}
	take, skip := dfs(root)
	return max(take, skip)
}

