class Flatten2D:
    """Iterates a list of lists in order, skipping empty rows."""

    def __init__(self, rows: list[list[int]]):
        self.rows, self.r, self.c = rows, 0, 0

    def has_next(self) -> bool:
        while self.r < len(self.rows) and self.c == len(self.rows[self.r]):
            self.r, self.c = self.r + 1, 0  # skip finished and empty rows
        return self.r < len(self.rows)

    def next(self) -> int:
        if not self.has_next():
            raise StopIteration
        self.c += 1
        return self.rows[self.r][self.c - 1]

