// Iterates a vector of vectors in order, skipping empty rows.
class Flatten2D {
    vector<vector<int>> rows;  // own a copy: a temporary argument would dangle
    size_t r = 0, c = 0;

public:
    Flatten2D(vector<vector<int>> rows) : rows(std::move(rows)) {}

    bool hasNext() {
        while (r < rows.size() && c == rows[r].size()) r++, c = 0;  // skip finished and empty rows
        return r < rows.size();
    }

    int next() {
        if (!hasNext()) throw out_of_range("no more elements");
        return rows[r][c++];
    }
};

