    @Override
    public boolean hasNext() {
        while (r < rows.size() && c == rows.get(r).size()) { // skip finished and empty rows
            r++;
            c = 0;
        }
        return r < rows.size();
    }

    @Override
    public Integer next() {
        if (!hasNext()) throw new NoSuchElementException();
        return rows.get(r).get(c++);
    }
}

