class LRUCache {
    int cap;
    list<pair<int, int>> items;                               // front = most recently used
    unordered_map<int, list<pair<int, int>>::iterator> pos;   // key -> its node in items

public:
    LRUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        auto it = pos.find(key);
        if (it == pos.end()) return -1;
        items.splice(items.begin(), items, it->second);  // move to front in O(1)
        return it->second->second;
    }

    void put(int key, int value) {
        if (auto it = pos.find(key); it != pos.end()) {
            it->second->second = value;
            items.splice(items.begin(), items, it->second);
            return;
        }
        items.emplace_front(key, value);
        pos[key] = items.begin();
        if ((int)items.size() > cap) {
            pos.erase(items.back().first);  // evict the least recently used
            items.pop_back();
        }
    }
};

