import "container/list"

type entry struct{ key, value int }

type LRUCache struct {
	cap   int
	order *list.List            // front = most recently used
	pos   map[int]*list.Element // key -> its element in order
}

func NewLRUCache(capacity int) *LRUCache {
	return &LRUCache{cap: capacity, order: list.New(), pos: map[int]*list.Element{}}
}

func (c *LRUCache) Get(key int) int {
	el, ok := c.pos[key]
	if !ok {
		return -1
	}
	c.order.MoveToFront(el)
	return el.Value.(*entry).value
}

func (c *LRUCache) Put(key, value int) {
	if el, ok := c.pos[key]; ok {
		el.Value.(*entry).value = value
		c.order.MoveToFront(el)
		return
	}
	c.pos[key] = c.order.PushFront(&entry{key, value})
	if c.order.Len() > c.cap {
		oldest := c.order.Back() // evict the least recently used
		c.order.Remove(oldest)
		delete(c.pos, oldest.Value.(*entry).key)
	}
}

