// Lowercase words. Nodes live in one vector; child index 0 means "none" (0 is the root).
class Trie {
    struct Node {
        array<int, 26> next{};
        int prefix = 0, words = 0;  // words passing through / ending exactly here
    };
    vector<Node> nodes = vector<Node>(1);

    int walk(const string& s) const {  // node index for s, or -1
        int cur = 0;
        for (char ch : s)
            if (!(cur = nodes[cur].next[ch - 'a'])) return -1;
        return cur;
    }

public:
    void insert(const string& word) {
        int cur = 0;
        for (char ch : word) {
            int c = ch - 'a';
            if (!nodes[cur].next[c]) {
                nodes[cur].next[c] = nodes.size();
                nodes.emplace_back();  // may reallocate: never hold a Node& across this
            }
            cur = nodes[cur].next[c];
            nodes[cur].prefix++;
        }
        nodes[cur].words++;
    }

    int countWord(const string& word) const {
        int i = walk(word);
        return i < 0 ? 0 : nodes[i].words;
    }

    int countPrefix(const string& prefix) const {
        int i = walk(prefix);
        return i < 0 ? 0 : nodes[i].prefix;
    }
};

