        Trie node = this;
        for (char ch : word.toCharArray()) {
            int c = ch - 'a';
            if (node.next[c] == null) node.next[c] = new Trie();
            node = node.next[c];
            node.prefix++;
        }
        node.words++;
    }

    private Trie walk(String s) {
        Trie node = this;
        for (char ch : s.toCharArray()) {
            node = node.next[ch - 'a'];
            if (node == null) return null;
        }
        return node;
    }

    int countWord(String word) {
        Trie node = walk(word);
        return node == null ? 0 : node.words;
    }

    int countPrefix(String prefix) {
        Trie node = walk(prefix);
        return node == null ? 0 : node.prefix;
    }
}

