// Trie stores lowercase words.
type Trie struct {
	next   [26]*Trie
	prefix int // words passing through this node
	words  int // words ending exactly here
}

func (t *Trie) Insert(word string) {
	node := t
	for i := 0; i < len(word); i++ {
		c := word[i] - 'a'
		if node.next[c] == nil {
			node.next[c] = &Trie{}
		}
		node = node.next[c]
		node.prefix++
	}
	node.words++
}

func (t *Trie) walk(s string) *Trie {
	node := t
	for i := 0; i < len(s) && node != nil; i++ {
		node = node.next[s[i]-'a']
	}
	return node
}

func (t *Trie) CountWord(word string) int {
	if node := t.walk(word); node != nil {
		return node.words
	}
	return 0
}

func (t *Trie) CountPrefix(prefix string) int {
	if node := t.walk(prefix); node != nil {
		return node.prefix
	}
	return 0
}

